<span class="line"><span style="color:#89DDFF;">  (</span><span style="color:#BABED8;font-style:italic;">arg</span><span style="color:#89DDFF;">:</span><span style="color:#FFCB6B;"> T</span><span style="color:#89DDFF;">):</span><span style="color:#FFCB6B;"> T</span><span style="color:#89DDFF;">;</span></span>
